package com.ricozknow.enterprise.settings; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/admin/tenant-settings") @RequiredArgsConstructor public class TenantSettingsController {private final TenantSettingsService service; @GetMapping @PreAuthorize("hasRole('ADMIN')") public TenantSettings get(){return service.getOrCreate();} @PutMapping @PreAuthorize("hasRole('ADMIN')") public TenantSettings save(@RequestBody TenantSettings s){return service.save(s);} }
